    while True:
        await asyncio.to_thread(simulate_once)
        await asyncio.sleep(SIMULATE_INTERVAL)


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    simulate_once()  # 启动即采集一轮，避免首页无数据
    task = asyncio.create_task(simulator_loop())
    yield
    task.cancel()


